  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
#pragma warning disable 162, 1522
    switch (action)
    {
      case 2: // program -> definitions
{ root = new ProgramNode(ValueStack[ValueStack.Depth-1].dListVal); CurrentSemanticValue.pVal = (ProgramNode)root; }
        break;
      case 3: // definitions -> definition
{ CurrentSemanticValue.dListVal = new List<CellDefNode> { ValueStack[ValueStack.Depth-1].cDefVal }; }
        break;
      case 4: // definitions -> definitions, definition
{ CurrentSemanticValue.dListVal = ValueStack[ValueStack.Depth-2].dListVal; ValueStack[ValueStack.Depth-2].dListVal.Add(ValueStack[ValueStack.Depth-1].cDefVal); }
        break;
      case 5: // definition -> CELLREF, ASSIGN, expr
{ CurrentSemanticValue.cDefVal = new CellDefNode(new CellRefNode(ValueStack[ValueStack.Depth-3].sVal), ValueStack[ValueStack.Depth-1].eVal); }
        break;
      case 6: // definition -> NAME, ASSIGN, expr
{ CurrentSemanticValue.cDefVal = new CellDefNode(new NameNode(ValueStack[ValueStack.Depth-3].sVal), ValueStack[ValueStack.Depth-1].eVal); }
        break;
      case 7: // definition -> NAME, LPAREN, params, RPAREN, ASSIGN, expr
{ CurrentSemanticValue.cDefVal = new CellDefNode(new NameNode(ValueStack[ValueStack.Depth-6].sVal), new LambdaNode(ValueStack[ValueStack.Depth-4].sListVal, ValueStack[ValueStack.Depth-1].eVal)); }
        break;
      case 8: // expr -> expr, EQ, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "="); }
        break;
      case 9: // expr -> expr, NEQ, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "<>"); }
        break;
      case 10: // expr -> expr, LT, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "<"); }
        break;
      case 11: // expr -> expr, GT, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, ">"); }
        break;
      case 12: // expr -> expr, LEQ, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "<="); }
        break;
      case 13: // expr -> expr, GEQ, additive
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, ">="); }
        break;
      case 14: // expr -> additive
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 15: // additive -> additive, PLUS, multiplicative
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "+"); }
        break;
      case 16: // additive -> additive, MINUS, multiplicative
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "-"); }
        break;
      case 17: // additive -> additive, CONCAT, multiplicative
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "&"); }
        break;
      case 18: // additive -> multiplicative
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 19: // multiplicative -> multiplicative, MULT, power
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "*"); }
        break;
      case 20: // multiplicative -> multiplicative, DIV, power
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "/"); }
        break;
      case 21: // multiplicative -> power
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 22: // power -> power, POW, primary
{ CurrentSemanticValue.eVal = new BinOpNode(ValueStack[ValueStack.Depth-3].eVal, ValueStack[ValueStack.Depth-1].eVal, "^"); }
        break;
      case 23: // power -> primary
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 24: // primary -> MINUS, primary
{ CurrentSemanticValue.eVal = new UnaryOpNode(ValueStack[ValueStack.Depth-1].eVal, "-"); }
        break;
      case 25: // primary -> PLUS, primary
{ CurrentSemanticValue.eVal = new UnaryOpNode(ValueStack[ValueStack.Depth-1].eVal, "+"); }
        break;
      case 26: // primary -> atom
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 27: // atom -> NUMBER
{ CurrentSemanticValue.eVal = new NumberNode(ValueStack[ValueStack.Depth-1].iVal); }
        break;
      case 28: // atom -> REAL
{ CurrentSemanticValue.eVal = new NumberNode(ValueStack[ValueStack.Depth-1].dVal); }
        break;
      case 29: // atom -> STRING
{ CurrentSemanticValue.eVal = new StringNode(ParserHelper.UnescapeString(ValueStack[ValueStack.Depth-1].sVal)); }
        break;
      case 30: // atom -> BOOL
{ CurrentSemanticValue.eVal = new BoolNode(ValueStack[ValueStack.Depth-1].bVal); }
        break;
      case 31: // atom -> ERROR
{ CurrentSemanticValue.eVal = new ErrorNode(ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 32: // atom -> CELLREF
{ CurrentSemanticValue.eVal = new CellRefNode(ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 33: // atom -> COLREF
{ CurrentSemanticValue.eVal = new ColRefNode(ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 34: // atom -> ROWREF
{ CurrentSemanticValue.eVal = new RowRefNode(ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 35: // atom -> NAME
{ CurrentSemanticValue.eVal = new NameNode(ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 36: // atom -> call
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 37: // atom -> range
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 38: // atom -> sheetref
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 39: // atom -> LPAREN, expr, RPAREN
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-2].eVal; }
        break;
      case 40: // atom -> lambda
{ CurrentSemanticValue.eVal = ValueStack[ValueStack.Depth-1].eVal; }
        break;
      case 41: // call -> FUNCNAME, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode(ValueStack[ValueStack.Depth-4].sVal, ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 42: // call -> FUNCNAME, LPAREN, RPAREN
{ CurrentSemanticValue.eVal = new CallNode(ValueStack[ValueStack.Depth-3].sVal, new List<ExprNode>()); }
        break;
      case 43: // call -> NAME, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode(ValueStack[ValueStack.Depth-4].sVal, ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 44: // call -> NAME, LPAREN, RPAREN
{ CurrentSemanticValue.eVal = new CallNode(ValueStack[ValueStack.Depth-3].sVal, new List<ExprNode>()); }
        break;
      case 45: // call -> MAP, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("MAP", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 46: // call -> FILTER, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("FILTER", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 47: // call -> REDUCE, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("REDUCE", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 48: // call -> SORT, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("SORT", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 49: // call -> UNIQUE, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("UNIQUE", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 50: // call -> LAMBDA, LPAREN, args, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("LAMBDA", ValueStack[ValueStack.Depth-2].eListVal); }
        break;
      case 51: // call -> LAMBDA, LPAREN, RPAREN
{ CurrentSemanticValue.eVal = new CallNode("LAMBDA", new List<ExprNode>()); }
        break;
      case 52: // lambda -> NAME, ARROW, expr
{ CurrentSemanticValue.eVal = new LambdaNode(new List<string> { ValueStack[ValueStack.Depth-3].sVal }, ValueStack[ValueStack.Depth-1].eVal); }
        break;
      case 53: // lambda -> LPAREN, params, RPAREN, ARROW, expr
{ CurrentSemanticValue.eVal = new LambdaNode(ValueStack[ValueStack.Depth-4].sListVal, ValueStack[ValueStack.Depth-1].eVal); }
        break;
      case 54: // range -> CELLREF, COLON, CELLREF
{ CurrentSemanticValue.eVal = new RangeNode(ValueStack[ValueStack.Depth-3].sVal, ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 55: // sheetref -> NAME, BANG, CELLREF
{ CurrentSemanticValue.eVal = new SheetRefNode(ValueStack[ValueStack.Depth-3].sVal, ValueStack[ValueStack.Depth-1].sVal); }
        break;
      case 56: // args -> expr
{ CurrentSemanticValue.eListVal = new List<ExprNode> { ValueStack[ValueStack.Depth-1].eVal }; }
        break;
      case 57: // args -> args, COMMA, expr
{ CurrentSemanticValue.eListVal = ValueStack[ValueStack.Depth-3].eListVal; ValueStack[ValueStack.Depth-3].eListVal.Add(ValueStack[ValueStack.Depth-1].eVal); }
        break;
      case 58: // params -> NAME
{ CurrentSemanticValue.sListVal = new List<string> { ValueStack[ValueStack.Depth-1].sVal }; }
        break;
      case 59: // params -> params, COMMA, NAME
{ CurrentSemanticValue.sListVal = ValueStack[ValueStack.Depth-3].sListVal; ValueStack[ValueStack.Depth-3].sListVal.Add(ValueStack[ValueStack.Depth-1].sVal); }
        break;
    }
#pragma warning restore 162, 1522
  }

  protected override string TerminalToString(int terminal)
  {
    if (aliasses != null && aliasses.ContainsKey(terminal))
        return aliasses[terminal];
    else if (((Tokens)terminal).ToString() != terminal.ToString(CultureInfo.InvariantCulture))
        return ((Tokens)terminal).ToString();
    else
        return CharToString((char)terminal);
  }

}
